export type TemaGaleria = "farmacos" | "grupos" | "estereo" | "conformacoes";

export const TEMAS_GALERIA: Record<TemaGaleria, string> = {"farmacos": "Fármacos", "grupos": "Grupos funcionais", "estereo": "Estereoquímica", "conformacoes": "Conformações e aromáticos"};

export interface MoleculaGaleria {
  chave: string;
  nome: string;
  /** Nome em inglês (como no PubChem), usado na busca. */
  nomeEn: string;
  tema: TemaGaleria;
  /** SMILES em Kekulé, com estereoquímica, para o bastão 2D. */
  smiles: string;
  /** SMILES isomérico canônico (RDKit), usado para achar o CID no PubChem. */
  smilesIsomerico: string;
  formula: string;
  massaMolar: number;
  /** logP de Crippen (RDKit). */
  logP: number;
  /** TPSA de Ertl (Å²). */
  tpsa: number;
  /** Contagens originais de Lipinski: NH + OH e N + O. */
  doadoresH: number;
  aceptoresH: number;
  sdf: string;
}

